import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import test from 'node:test';
import {LINKED_COMMON_PRESET,linkedCommonParametersAt,parseLinkedCommonResult,
  validateLinkedCommonQuery} from '../../src/app/curvedLinkedCommonParameter';

// Generated by the project's independent Python/Taylor/Darboux backend;
// this fixture is not saved Mathematica output and preserves the nonzero q1.
const fixture=JSON.parse(readFileSync(new URL('../fixtures/origamica-linked-common-parameter8.json',import.meta.url),'utf8'));
const requested={...LINKED_COMMON_PRESET,segments:8};

test('all four corrected bands keep nonzero source physical input and full finite interval',()=>{
  const result=parseLinkedCommonResult(fixture,requested);
  assert.equal(result.certification.bandCount,4);
  assert.deepEqual(result.query.q1Harmonics,[.1]);
  assert.equal(result.source.savedPhysicalInputsPreserved,true);
  assert.equal(result.certification.adoptableCreasePattern,false);
  assert.equal(result.certification.selfCollisionChecked,false);
  assert.equal(result.sample.rows[2].foldedCurves.length,5);
  assert.ok(result.diagnostics.maxMetricError<1e-9);
  assert.ok(Math.abs(result.sample.rows[0].foldAnglesDeg[1]+110.56999209210358)<1e-9);
});

test('client evaluates Taylor parameter transport for all curve values and derivatives',()=>{
  for(const row of fixture.sample.rows){
    const calculated=linkedCommonParametersAt(requested,row.s);
    for(const key of ['qValues','qDerivatives','foldAnglesDeg'] as const)
      row[key].forEach((value:number,i:number)=>assert.ok(Math.abs(value-calculated[key][i])<1e-9));
  }
});

test('query snapshots round trip exactly and keep true parameter variants',()=>{
  const q=validateLinkedCommonQuery({...requested,radii:[1,1.15,1.35],q1Harmonics:[.04,.002],firstFoldAngleDeg:-95,parameterStart:.2});
  assert.deepEqual(validateLinkedCommonQuery(JSON.parse(JSON.stringify(q))),q);
  for(const patch of [{segments:true},{radii:[1,1.01,1.2]},{q1Harmonics:[.1,.2]},
    {firstFoldAngleDeg:0},{parameterEnd:4},{unused:1}])
    assert.throws(()=>validateLinkedCommonQuery({...requested,...patch}));
});

test('strict readback rejects source relabeling, dropped bands, false FOLD and domain claims',()=>{
  const changes=[
    (r:typeof fixture)=>{r.source.savedNumericalOut=true;},
    (r:typeof fixture)=>{r.source.savedPhysicalInputsPreserved=false;},
    (r:typeof fixture)=>{r.source.formulaCorrections.pop();},
    (r:typeof fixture)=>{r.certification.adoptableCreasePattern=true;},
    (r:typeof fixture)=>{r.certification.selfCollisionChecked=true;},
    (r:typeof fixture)=>{r.certification.bandCount=1;},
    (r:typeof fixture)=>{r.diagnostics.parameterDomain.minimumSpeedLowerBound=1.5;},
    (r:typeof fixture)=>{r.diagnostics.parameterDomain.planarAngularSpanUpperBound=7;},
    (r:typeof fixture)=>{r.diagnostics.parameterDomain.roundingModel='exact real proof';},
    (r:typeof fixture)=>{r.sample.rows[1].foldedCurves.pop();},
    (r:typeof fixture)=>{r.sample.rows[2].flatDerivatives[4][0]+=.01;},
    (r:typeof fixture)=>{r.sample.rows[2].foldedDerivatives[3][2]+=.01;},
    (r:typeof fixture)=>{r.sample.rows[2].foldAnglesDeg[2]+=.01;},
    (r:typeof fixture)=>{r.sample.rows[2].qValues[3]+=.01;},
    (r:typeof fixture)=>{r.sample.rows[2].foldedCurves[4][2]+=.01;},
  ];
  for(const change of changes){const data=structuredClone(fixture);change(data);assert.throws(()=>parseLinkedCommonResult(data,requested));}
  assert.throws(()=>parseLinkedCommonResult(fixture,{...requested,segments:16}));
});

test('intrinsically isometric flat spatial spoof fails the actual signed crease angles',()=>{
  const flat=structuredClone(fixture);
  for(const row of flat.sample.rows){
    row.foldedCurves=row.flatCurves.map((p:number[])=>[...p,0]);
    row.foldedDerivatives=row.flatDerivatives.map((p:number[])=>[...p,0]);
  }
  flat.diagnostics.endpointSpatialSeparation=Math.max(...flat.sample.rows[0].foldedCurves.map((p:number[],j:number)=>
    Math.hypot(...p.map((x,k)=>x-flat.sample.rows.at(-1).foldedCurves[j][k]))));
  assert.throws(()=>parseLinkedCommonResult(flat,requested));
  const shifted=structuredClone(fixture);
  for(const row of shifted.sample.rows)for(const p of row.foldedCurves)p[0]+=2;
  assert.throws(()=>parseLinkedCommonResult(shifted,requested),'saved initial point and frame are part of the call contract');
});
